                8'h0b: out_data <= 8'h2b;  
                8'h0c: out_data <= 8'hfe;  
                8'h0d: out_data <= 8'hd7;  
                8'h0e: out_data <= 8'hab;  
                8'h0f: out_data <= 8'h76;  
