        if (reset) begin  
            data_out <= 5'b00000;  
            serial_out <= 1'b0;  
        end else if (load) begin  
            data_out <= data_in;  
            serial_out <= data_in[0];  
        end else begin  
            serial_out <= data_out[0];  
            data_out <= {1'b0, data_out[4:1]};  
        end  
    end  
